API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(api_gateway, "API Gateway") {
    Component(Request_Router, "Request Router", "Reverse Proxy / API Gateway Engine", "Routes incoming requests from the Frontend Container to the Core Domain Containers using internal gRPC/REST.")
    Component(Authentication_Authorization_Module, "Authentication & Authorization Module", "JWT & MFA Validator", "Validates JWT tokens and multi-factor authentication for all incoming HTTPS requests.")
    Component(Rate_Limiting_Module, "Rate Limiting Module", "Redis Rate Limiter Client", "Enforces edge throttling using the Redis Distributed Rate Limiting Store.")
}

Rel(Request_Router, Authentication_Authorization_Module, "Delegates request validation")
Rel(Request_Router, Rate_Limiting_Module, "Checks rate limits")
@enduml

Integration / FHIR Adapter Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Integration / FHIR Adapter Container container

Container_Boundary(integration_fhir_adapter_container, "Integration / FHIR Adapter Container") {
    Component(FHIR_API_Router, "FHIR API Router", "Node.js / Express", "Routes incoming HL7 FHIR requests from external lab and imaging systems.")
    Component(Anti_Corruption_Layer_ACL_Transformer, "Anti-Corruption Layer (ACL) Transformer", "TypeScript", "Translates external HL7 FHIR payloads into internal domain models and vice versa.")
    Component(Rate_Limiting_Middleware, "Rate Limiting Middleware", "Redis Client", "Enforces traffic throttling and idempotency checks using the Redis Distributed Rate Limiting Store.")
}

Rel(FHIR_API_Router, Anti_Corruption_Layer_ACL_Transformer, "Forwards validated payloads for transformation")
Rel(FHIR_API_Router, Rate_Limiting_Middleware, "Checks request rate limits and idempotency")

@enduml

Asynchronous Event Bus.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Asynchronous Event Bus container

Container_Boundary("Asynchronous Event Bus", "Asynchronous Event Bus") {
    Component("Centralized Schema Registry", "Centralized Schema Registry", "Avro / JSON Schema Registry", "Enforces strict backward and forward compatibility to prevent schema drift across services.")
    Component("Message Broker", "Message Broker", "Kafka/RabbitMQ", "Handles asynchronous, decoupled event-driven workflows and high availability with TLS and Envelope Encryption.")
    Component("Dead Letter Queues (DLQ)", "Dead Letter Queues (DLQ)", "AMQP/Kafka", "Routes malformed or failed messages for later inspection and error handling.")
}

Rel("Message Broker", "Dead Letter Queues (DLQ)", "Route malformed or failed messages", "AMQP/Kafka")
Rel("Centralized Schema Registry", "Message Broker", "Provides schema validation for events published across", "AMQP/Kafka with TLS and Envelope Encryption")

@enduml

Audit Logging & Compliance Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Audit Logging & Compliance Container container

Container_Boundary("Audit Logging & Compliance Container", "Audit Logging & Compliance Container") {
    Component("Audit Event Receiver", "Audit Event Receiver", "Node.js / Express API", "Receives security and compliance audit events from the Asynchronous Event Bus and core services.")
    Component("Compliance Validation Engine", "Compliance Validation Engine", "Python / HIPAA-GDPR Policy Engine", "Validates incoming events against strict HIPAA and GDPR regulations and ensures 10-year retention rules.")
    Component("WORM Storage Writer", "WORM Storage Writer", "AWS S3 SDK with Object Lock", "Writes tamper-resistant audit logs directly to Write-Once-Read-Many (WORM) storage for compliance mandates.")
}

Rel("Audit Event Receiver", "Compliance Validation Engine", "Forwards collected audit events for policy checking")
Rel("Compliance Validation Engine", "WORM Storage Writer", "Sends validated logs for immutable storage")
@enduml

Observability Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Observability Container container

Container_Boundary(observability_container, "Observability Container") {
    Component(Metrics_Collector, "Metrics Collector", "OpenTelemetry / Prometheus", "Collects operational metrics from all containers across the hybrid cloud platform.")
    Component(Distributed_Tracing_Agent, "Distributed Tracing Agent", "OpenTelemetry / W3C Trace Context", "Captures and propagates trace correlation IDs across synchronous and asynchronous boundaries.")
    Component(Log_Aggregator, "Log Aggregator", "OpenTelemetry", "Collects and sanitizes logs while ensuring HIPAA and GDPR compliance.")
}

Rel(Metrics_Collector, Distributed_Tracing_Agent, "Correlates metrics with distributed trace contexts", "")
Rel(Distributed_Tracing_Agent, Log_Aggregator, "Links trace IDs to corresponding system logs", "")

@enduml

