Database Migration Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(database_migration_container, "Database Migration Container") {
    Component(Migration_Execution_Engine, "Migration Execution Engine", "Kubernetes Job / Helm Hooks", "Executes declarative, version-locked database schema updates during deployments using least-privilege credentials.")
    Component(Distributed_Lock_Manager, "Distributed Lock Manager", "Distributed Advisory Locks", "Enforces single-instance migration execution in multi-replica Kubernetes environments.")
    Component(Pre_deployment_Validation_Worker, "Pre-deployment Validation Worker", "Init Containers", "Manages explicit dependency ordering to ensure migrations finish before core application traffic routes.")
}

Rel(Migration_Execution_Engine, Distributed_Lock_Manager, "Acquires locks via", "")
Rel(Pre_deployment_Validation_Worker, Migration_Execution_Engine, "Blocks application startup until completion of", "")

@enduml

Redis Distributed Rate Limiting Store.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Redis Distributed Rate Limiting Store container

Container_Boundary(redis_store, "Redis Distributed Rate Limiting Store") {
    Component(Rate_Limiting_Engine, "Rate Limiting Engine", "Lua Scripts", "Executes atomically within Redis for Token Bucket and Sliding Window algorithms to enforce low-latency rate limits.")
    Component(Caching_Store, "Caching Store", "Redis In-Memory Store", "Provides low-latency ephemeral caching and offloads ephemeral state from transactional databases.")
    Component(Metrics_Exporter, "Metrics Exporter", "OpenTelemetry / Redis Metrics", "Exposes Redis performance metrics such as evicted_keys and used_memory_rss for scraping via HTTP/gRPC.")
}

Rel(Rate_Limiting_Engine, Caching_Store, "Reads and writes rate limit state atomically using", "RESP")
Rel(Metrics_Exporter, Caching_Store, "Scrapes telemetry and performance metrics from", "HTTP/gRPC")

@enduml
